import { expect, expectStatus, test } from "../../fixtures";

test("A vendor from another tenant is not found", { tag: "@VEN-07" }, async ({ apiAs, factory }) => {
  // Arrange
  const outsider = await apiAs("otherTenant");
  const outsiderProfile = await expectStatus(await outsider.get("/api/me"), 200);
  expect(outsiderProfile.tenant.name, "the other persona belongs to Globex Procurement").toBe("Globex Procurement");
  const globexVendor = await factory.vendor({ as: "otherTenant" });
  const member = await apiAs("member");

  // Act
  const response = await member.get(`/api/vendors/${globexVendor.id}`);

  // Assert
  const body = await expectStatus(response, 404);
  expect(body.error.code).toBe("vendor_not_found");
});
